const tabId = 343605502;
const talks = await browserjs(tabId, () => {
  // Let's find all talk cards/links
  // In TED talks listing, each talk usually has an anchor with href starting with /talks/
  const talkLinks = Array.from(document.querySelectorAll('a[href*="/talks/"]'));
  // Filter out non-talk links like /talks itself
  const validTalks = talkLinks.filter(a => {
    const path = new URL(a.href).pathname;
    return path.startsWith('/talks/') && path !== '/talks' && path !== '/talks/';
  });

  // Extract info for each unique talk
  const seen = new Set();
  const results = [];
  for (const a of validTalks) {
    const href = a.href;
    if (seen.has(href)) continue;
    seen.add(href);

    // Find the closest container or card
    const card = a.closest('div[class*="talk"], div[class*="card"], div.flex-col, article') || a.parentElement;
    results.push({
      href,
      text: a.textContent.trim(),
      cardText: card ? card.textContent.trim().replace(/\s+/g, ' ') : ''
    });
  }
  return results;
});

console.log("Total unique talks found:", talks.length);
console.log(JSON.stringify(talks.slice(0, 10), null, 2));

