const talkStats = await browserjs(tabId, () => {
  const json = JSON.parse(document.querySelector('#__NEXT_DATA__').textContent);
  // Look through json for talk objects
  function findTalks(obj, results = []) {
    if (!obj || typeof obj !== 'object') return results;
    if (obj.title && (obj.viewedCount !== undefined || obj.viewCount !== undefined || obj.views !== undefined || obj.presenterDisplayName)) {
      results.push({
        title: obj.title,
        slug: obj.slug,
        presenter: obj.presenterDisplayName || (obj.speakers && obj.speakers[0]?.name),
        duration: obj.duration,
        viewCount: obj.viewedCount || obj.viewCount || obj.views || obj.viewed_count,
        topics: obj.topics
      });
    }
    for (const key of Object.keys(obj)) {
      findTalks(obj[key], results);
    }
    return results;
  }
  const found = findTalks(json.props);
  return {
    propsKeys: Object.keys(json.props),
    pagePropsKeys: json.props?.pageProps ? Object.keys(json.props.pageProps) : null,
    talksCount: found.length,
    sample: found.slice(0, 5)
  };
});
console.log(JSON.stringify(talkStats, null, 2));

