    "maurice_conti_the_incredible_inventions_of_intuitive_ai",
    "sam_harris_can_we_build_ai_without_losing_control_over_it",
    "vijay_kumar_robots_that_fly_and_cooperate",
    "andrew_mcafee_what_will_future_jobs_look_like",
    "marc_raibert_meet_spot_the_robot_dog_that_can_run_hop_and_open_doors"
  ];

  const results = [];
  for (const slug of slugs) {
    try {
      const resp = await fetch(`/talks/${slug}`);
      const text = await resp.text();
      const match = text.match(/"viewedCount":\s*(\d+)/);
      const titleMatch = text.match(/"title":\s*"([^"]+)"/);
      const durationMatch = text.match(/"duration":\s*(\d+)/);
      results.push({
        slug,
        title: titleMatch ? titleMatch[1] : null,
        duration: durationMatch ? Number(durationMatch[1]) : null,
        viewedCount: match ? Number(match[1]) : null
      });
    } catch (e) {
      results.push({ slug, error: e.message });
    }
  }
  return results;
});

console.log(JSON.stringify(checkOthers, null, 2));

