const tabId = 343605502;
// Let's check search results for "robots" with duration 12-18 and sort popular
const searchUrl = "https://www.ted.com/talks?q=robots&sort=popular&duration=12-18";
const searchResults = await browserjs(tabId, async (url) => {
  const resp = await fetch(url);
  const text = await resp.text();
  // Extract initialResults or hits
  const match = text.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (match) {
    try {
      const data = JSON.parse(match[1]);
      const initialResults = data.props?.pageProps?.serverState?.initialResults;
      if (initialResults) {
        const firstKey = Object.keys(initialResults)[0];
        const hits = initialResults[firstKey]?.results?.[0]?.hits;
        return hits?.slice(0, 5).map(h => ({
          title: h.title,
          speakers: h.speakers,
          duration: h.duration,
          slug: h.slug
        }));
      }
    } catch (e) {
      return { error: e.message };
    }
  }
  return { noMatch: true };
}, searchUrl);
console.log(JSON.stringify(searchResults, null, 2));

