const tabId = 343605502;
const talkTopics = await browserjs(tabId, async () => {
  const resp = await fetch("/talks/chris_anderson_ted_questions_no_one_knows_the_answers_to");
  const text = await resp.text();
  const match = text.match(/"topics":\s*(\{[^}]+\}|\[[^\]]+\])/);
  const nextDataMatch = text.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (nextDataMatch) {
    const data = JSON.parse(nextDataMatch[1]);
    const v = data.props?.pageProps?.videoData;
    return {
      title: v?.title,
      topics: v?.topics?.nodes?.map(t => t.name),
      viewedCount: v?.viewedCount,
      duration: v?.duration
    };
  }
  return null;
});
console.log(JSON.stringify(talkTopics, null, 2));

